declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';header('Content-Type: application/json; charset=utf-8');$expected=(string)($config['SYNC_TOKEN']??'');$auth=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(strlen($expected)<32||!preg_match('/^Bearer\s+(.+)$/',$auth,$m)||!hash_equals($expected,$m[1])){http_response_code(401);exit(json_encode(['ok'=>false]));}$input=json_decode((string)file_get_contents('php://input'),true);$numbers=array_values(array_filter(array_map('strval',$input['operaciones']??[])));if($_SERVER['REQUEST_METHOD']!=='POST'||count($numbers)>250){http_response_code(422);exit(json_encode(['ok'=>false]));}$find=$db->prepare("SELECT o.id operacion_id,o.cliente_id,c.numero_documento FROM operaciones o JOIN clientes c ON c.id=o.cliente_id WHERE o.cedente='SMA_INVERSIONES' AND o.numero_operacion=?");$insert=$db->prepare("INSERT INTO documentos(acuerdo_id,cliente_id,operacion_id,tipo,estado,nombre_descarga,solicitado_por) VALUES(NULL,?,?,'CESION_DERECHOS','PENDIENTE',?,NULL) ON DUPLICATE KEY UPDATE estado=IF(estado='ERROR','PENDIENTE',estado),updated_at=NOW()");$created=0;foreach($numbers as $number){$find->execute([$number]);if($row=$find->fetch()){$dni=preg_replace('/\D/','',$row['numero_documento']);$insert->execute([$row['cliente_id'],$row['operacion_id'],"Cesión de Derechos - DNI_$dni.pdf"]);$created++;}}echo json_encode(['ok'=>true,'prepared'=>$created]);
